args.command:
cd ~; python3 - <<'EOF'
import workcell as w, sys
jar, tare = "J1", 119.96
target = 250.0
def net():
    r = w.call("scale","read")
    return r.data["gross_g"] - tare
n = net()
while n < target-50: w.call("robot","dose","bulk"); n=net()
while n < target-10: w.call("robot","dose","coarse"); n=net()
while n < target-0.6: w.call("robot","dose","fine"); n=net()
while n < target-0.05:
    w.call("robot","dose","micro"); n=net()
    if n > target+0.2:
        w.call("robot","remove"); n=net()
print("net", n)
r = w.call("checkweigher","check"); print(r.text, r.ok)
w.call("robot","pick",jar); w.call("robot","place","rack")
EOF

